mapper.select:
SELECT t.*, s.full_name AS student_name, u.full_name AS therapist_name
FROM therapy_sessions t
JOIN students s ON s.id = t.student_id
JOIN users u    ON u.id = t.therapist_id
WHERE t.start_time < #{to}
  AND t.start_time >= #{from}
  AND t.student_id IN
  #{sid}
ORDER BY t.start_time

SELECT * FROM school_calendar
WHERE event_date BETWEEN #{from} AND #{to}
ORDER BY event_date
